using System;using System.Collections;using System.IO;using UnityEngine;using WaveHarmonic.Crest;using CityForge.CameraSystem;
namespace CityForge.World {
public sealed class CoastlineAcceptance:MonoBehaviour {
 const string Output="/Users/joelinstrum/Documents/Codex/2026-10-12/begin-from-this-handoff-and-start/outputs/";
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Launch(){if(!Application.isEditor&&Array.Exists(System.Environment.GetCommandLineArgs(),a=>a=="--coastline-test"))new GameObject("Coastline acceptance").AddComponent<CoastlineAcceptance>();}
 IEnumerator Start(){
 Application.runInBackground=true;yield return null;
 if(!FindFirstObjectByType<PrototypeRegionView>()){var fixture=SavedRegionStore.Load(Output+"Coastline-Test.cfregion");PrototypeRegionView.Open(fixture.info.name,FindFirstObjectByType<Canvas>(),snapshot:fixture);}

 yield return new WaitForSecondsRealtime(1);
 var view=FindFirstObjectByType<PrototypeRegionView>();var land=view.ApprovedDistrict;land.SetTreesEnabled(true);land.SetSmallPlantsEnabled(true);land.SetFramePacing60(true);var water=land.Water;
 if(!view.Coastline||!water||!water.AnimatedWavesLod.Enabled||!land.GetComponentInChildren<ShapeFFT>())throw new Exception("Coastline must use Crest FFT ocean");
 if(water.TimeProvider is not CoastalWaterClock||Mathf.Abs(water.TimeProvider.Delta-Time.deltaTime*CoastalWaterClock.Speed)>.001f)throw new Exception("Ocean clock must run at 45 percent speed");
 var swell=land.GetComponentInChildren<ShapeFFT>();if(!swell.OverrideGlobalWindTurbulence||swell.WindTurbulence>.02f||swell.WindAlignment<.9f||Mathf.Abs(swell.WaveDirectionHeadingAngle)>.01f)throw new Exception("Coastal waves must travel east toward the beach");
 if(!water.FoamLod.Enabled||water.Surface.Material.GetFloat("_Crest_FoamEnabled")<.5f||!water.Surface.Material.GetTexture("_Crest_FoamTexture"))throw new Exception("Coastal surf foam missing");
 if(!land.GetComponentInChildren<FoamLodInput>())throw new Exception("Animated shoreline input missing");
 var footprint=land.GetComponentInChildren<WaterBody>();if(!footprint||!water.ClipLod.Enabled||water.ClipLod.DefaultClippingState!=DefaultClippingState.EverythingClipped||Mathf.Abs(footprint.transform.lossyScale.x-land.Side)>.1f||Mathf.Abs(footprint.transform.lossyScale.z-land.Side)>.1f)throw new Exception("Ocean containment failed");
 int wet=0;const int samples=256;for(int z=0;z<samples;z++)for(int x=0;x<samples;x++)if(land.DisplayTerrain.terrainData.GetInterpolatedHeight((x+.5f)/samples,(z+.5f)/samples)<view.SeaLevel)wet++;float waterFraction=wet/(float)(samples*samples);if(Mathf.Abs(waterFraction-.30f)>.01f)throw new Exception("Ocean fraction: "+waterFraction);
 var rig=view.GetComponentInChildren<CityForgeCameraController>();yield return new WaitForSecondsRealtime(4);
 yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Output+"Coastline-Bounded-"+(Application.isEditor?"":"Player-")+"Isometric.png");yield return null;
 var foamTexture=(Texture)typeof(Lod).GetProperty("DataTexture",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).GetValue(water.FoamLod);var foamBefore=UnityEngine.Rendering.AsyncGPUReadback.Request(foamTexture,0,TextureFormat.RFloat);while(!foamBefore.done)yield return null;if(foamBefore.hasError)throw new Exception("Foam readback failed");var beforeValues=new float[foamBefore.layerCount][];for(int layer=0;layer<beforeValues.Length;layer++)beforeValues[layer]=foamBefore.GetData<float>(layer).ToArray();
 yield return new WaitForSecondsRealtime(3.75f);yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Output+"Coastline-Surf-"+(Application.isEditor?"Editor":"Player")+"-Later.png");yield return null;
 foamTexture=(Texture)typeof(Lod).GetProperty("DataTexture",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).GetValue(water.FoamLod);var foamAfter=UnityEngine.Rendering.AsyncGPUReadback.Request(foamTexture,0,TextureFormat.RFloat);while(!foamAfter.done)yield return null;if(foamAfter.hasError)throw new Exception("Foam readback failed");double foamChange=0;for(int layer=0;layer<beforeValues.Length;layer++){var afterValues=foamAfter.GetData<float>(layer);for(int i=0;i<afterValues.Length;i++)foamChange+=Math.Abs(beforeValues[layer][i]-afterValues[i]);}File.WriteAllText(Output+"Coastline-Surf-Diagnostics.txt","change="+foamChange+" samples="+beforeValues.Length+" texture="+foamTexture.name+" crestTime="+water.TimeProvider.Time+" delta="+water.TimeProvider.Delta+" surfTime="+land.GetComponentInChildren<FoamLodInput>().GetComponent<Renderer>().sharedMaterial.GetFloat("_SurfTime"));if(foamChange<1)throw new Exception("Surf foam is not changing over time");
 rig.ToggleViewAngle();yield return new WaitForSecondsRealtime(3);if(Mathf.Abs(water.Surface.Material.GetFloat("_Crest_NormalMapStrength")-.15f)>.001f||Mathf.Abs(water.Surface.Material.GetFloat("_Crest_Smoothness")-.8f)>.001f||Mathf.Abs(water.Surface.Material.GetFloat("_Crest_PlanarReflectionsIntensity")-.65f)>.001f)throw new Exception("Accepted lower-view profile changed");yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Output+"Coastline-Bounded-"+(Application.isEditor?"":"Player-")+"Lower.png");yield return null;rig.ToggleViewAngle();
 var snapshot=SavedRegionStore.Capture(view);if(Application.isEditor)SavedRegionStore.Save(snapshot);SavedRegionStore.Write(snapshot,Output+"Coastline-Test.cfregion");var restored=SavedRegionStore.Load(Output+"Coastline-Test.cfregion");if(!restored.info.coastline||restored.info.waterless||restored.info.coastVersion!=2||restored.info.terrainHeightRange!=160||restored.data.WaterBodies.Length!=1||restored.data.WaterBodies[0].kind!=WaterBodyKind.Ocean)throw new Exception("Coastal metadata lost");
 var treeCount=land.FullTreeCount;view.ReturnToMenu();yield return null;yield return null;PrototypeRegionView.Open(restored.info.name,FindFirstObjectByType<Canvas>(),snapshot:restored);view=FindFirstObjectByType<PrototypeRegionView>();yield return new WaitForSecondsRealtime(1);if(!view.Coastline||view.ApprovedDistrict.FullTreeCount!=treeCount||!view.ApprovedDistrict.Water.AnimatedWavesLod.Enabled)throw new Exception("Coastal scene reload failed");view.ApprovedDistrict.SetTreesEnabled(true);view.ApprovedDistrict.SetSmallPlantsEnabled(true);view.ApprovedDistrict.SetFramePacing60(true);
 File.WriteAllText(Output+"Coastline-Bounded-"+(Application.isEditor?"Editor":"Player")+"-Checks.txt","PASS: ocean area="+(waterFraction*100).ToString("F2")+"%; 1024m district / 2048m region; clipped to matching square/diamond footprint; lower-view normal/smoothness/reflection profile preserved; curved sand beach and rocky headland; Crest Animated Waves + shoreward FFT at 18km/h and 0.55 weight, heading +X, alignment 0.95 and turbulence 0.015; animated shoreline foam input, GPU foam change="+foamChange.ToString("F2")+" and time-separated captures; seabed depth probe; isometric/lower captures; coastal metadata and cached terrain saved and reopened.\n");Debug.Log("PASS Coastline Test checks");if(Application.isEditor)Destroy(gameObject);else Application.Quit(0);
 }
}}
